import React, { useState, useEffect } from 'react';
import axios from 'axios';

const CustomerInvoice = ({ token }) => {
  const [customers, setCustomers] = useState([]);
  const [entries, setEntries] = useState([]);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [showAddCustomer, setShowAddCustomer] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [selectedEntries, setSelectedEntries] = useState([]);

  const [customerForm, setCustomerForm] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    gst: ''
  });

  useEffect(() => {
    if (token) {
      fetchData();
    }
  }, [token]);

  const fetchData = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/ledger', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(response.data.entries);

      // Load customers from localStorage
      const savedCustomers = localStorage.getItem('customers');
      if (savedCustomers) {
        setCustomers(JSON.parse(savedCustomers));
      }
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const handleAddCustomer = () => {
    if (!customerForm.name || !customerForm.email) {
      alert('Name and Email are required');
      return;
    }

    const newCustomer = {
      id: Date.now(),
      ...customerForm,
      createdAt: new Date().toISOString()
    };

    const updatedCustomers = [...customers, newCustomer];
    setCustomers(updatedCustomers);
    localStorage.setItem('customers', JSON.stringify(updatedCustomers));

    setCustomerForm({ name: '', email: '', phone: '', address: '', gst: '' });
    setShowAddCustomer(false);
  };

  const handleGenerateInvoice = () => {
    if (!selectedCustomer) {
      alert('Please select a customer first');
      return;
    }
    if (selectedEntries.length === 0) {
      alert('Please select at least one transaction');
      return;
    }
    console.log('Generating invoice for:', selectedCustomer, 'with entries:', selectedEntries);
    setShowInvoice(true);
  };

  const handlePrintInvoice = () => {
    window.print();
  };

  const toggleEntrySelection = (entryId) => {
    setSelectedEntries(prev => 
      prev.includes(entryId) 
        ? prev.filter(id => id !== entryId)
        : [...prev, entryId]
    );
  };

  const calculateTotal = () => {
    return entries
      .filter(e => selectedEntries.includes(e.id))
      .reduce((sum, e) => sum + parseFloat(e.amount), 0);
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR'
    }).format(amount);
  };

  const invoiceData = showInvoice && selectedCustomer && selectedEntries.length > 0 ? {
    invoiceNumber: `INV-${Date.now()}`,
    date: new Date().toLocaleDateString('en-IN'),
    customer: selectedCustomer,
    items: entries.filter(e => selectedEntries.includes(e.id)),
    subtotal: calculateTotal(),
    tax: calculateTotal() * 0.18,
    total: calculateTotal() * 1.18
  } : null;

  return (
    <div style={{ padding: '2rem', maxWidth: '1400px', margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ color: 'white', fontSize: '2rem', fontWeight: '700', marginBottom: '0.5rem' }}>
          Customer & Invoice Management
        </h1>
        <p style={{ color: '#94a3b8' }}>Manage customers and generate invoices for transactions</p>
      </div>

      {/* Action Buttons */}
      <div style={{ display: 'flex', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
        <button 
          onClick={() => setShowAddCustomer(!showAddCustomer)}
          style={{
            padding: '0.75rem 1.5rem',
            background: showAddCustomer ? '#1d1429' : 'linear-gradient(135deg, #8c2bee 0%, #7c3aed 100%)',
            color: 'white',
            border: showAddCustomer ? '1px solid #2d2438' : 'none',
            borderRadius: '0.5rem',
            fontWeight: '600',
            cursor: 'pointer',
            transition: 'all 0.2s'
          }}
        >
          {showAddCustomer ? 'Cancel' : 'Add Customer'}
        </button>
        <button 
          onClick={handleGenerateInvoice}
          disabled={!selectedCustomer || selectedEntries.length === 0}
          style={{
            padding: '0.75rem 1.5rem',
            background: selectedCustomer && selectedEntries.length > 0 
              ? 'linear-gradient(135deg, #10b981 0%, #059669 100%)'
              : '#1d1429',
            color: 'white',
            border: '1px solid #2d2438',
            borderRadius: '0.5rem',
            fontWeight: '600',
            cursor: selectedCustomer && selectedEntries.length > 0 ? 'pointer' : 'not-allowed',
            opacity: selectedCustomer && selectedEntries.length > 0 ? 1 : 0.6,
            transition: 'all 0.2s'
          }}
        >
          Generate Invoice {selectedCustomer && selectedEntries.length > 0 && `(${selectedEntries.length} items)`}
        </button>
        {selectedCustomer && (
          <div style={{
            padding: '0.75rem 1.5rem',
            background: 'rgba(140, 43, 238, 0.1)',
            border: '1px solid rgba(140, 43, 238, 0.3)',
            borderRadius: '0.5rem',
            color: '#8c2bee',
            fontWeight: '600',
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem'
          }}>
            {selectedCustomer.name}
          </div>
        )}
      </div>

      {/* Add Customer Form */}
      {showAddCustomer && (
        <div style={{
          background: 'rgba(29, 20, 41, 0.6)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(140, 43, 238, 0.1)',
          borderRadius: '0.75rem',
          padding: '2rem',
          marginBottom: '2rem'
        }}>
          <h3 style={{ color: 'white', marginBottom: '1.5rem' }}>Add New Customer</h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '1.5rem' }}>
            <div>
              <label style={{ display: 'block', color: '#cbd5e1', marginBottom: '0.5rem', fontWeight: '600' }}>Name *</label>
              <input
                type="text"
                value={customerForm.name}
                onChange={(e) => setCustomerForm({...customerForm, name: e.target.value})}
                style={{
                  width: '100%',
                  padding: '0.75rem',
                  background: '#1d1429',
                  border: '1px solid #2d2438',
                  borderRadius: '0.5rem',
                  color: '#f1f5f9'
                }}
              />
            </div>
            <div>
              <label style={{ display: 'block', color: '#cbd5e1', marginBottom: '0.5rem', fontWeight: '600' }}>Email *</label>
              <input
                type="email"
                value={customerForm.email}
                onChange={(e) => setCustomerForm({...customerForm, email: e.target.value})}
                style={{
                  width: '100%',
                  padding: '0.75rem',
                  background: '#1d1429',
                  border: '1px solid #2d2438',
                  borderRadius: '0.5rem',
                  color: '#f1f5f9'
                }}
              />
            </div>
            <div>
              <label style={{ display: 'block', color: '#cbd5e1', marginBottom: '0.5rem', fontWeight: '600' }}>Phone</label>
              <input
                type="tel"
                value={customerForm.phone}
                onChange={(e) => setCustomerForm({...customerForm, phone: e.target.value})}
                style={{
                  width: '100%',
                  padding: '0.75rem',
                  background: '#1d1429',
                  border: '1px solid #2d2438',
                  borderRadius: '0.5rem',
                  color: '#f1f5f9'
                }}
              />
            </div>
            <div>
              <label style={{ display: 'block', color: '#cbd5e1', marginBottom: '0.5rem', fontWeight: '600' }}>GST Number</label>
              <input
                type="text"
                value={customerForm.gst}
                onChange={(e) => setCustomerForm({...customerForm, gst: e.target.value})}
                style={{
                  width: '100%',
                  padding: '0.75rem',
                  background: '#1d1429',
                  border: '1px solid #2d2438',
                  borderRadius: '0.5rem',
                  color: '#f1f5f9'
                }}
              />
            </div>
          </div>
          <div style={{ marginTop: '1.5rem' }}>
            <label style={{ display: 'block', color: '#cbd5e1', marginBottom: '0.5rem', fontWeight: '600' }}>Address</label>
            <textarea
              value={customerForm.address}
              onChange={(e) => setCustomerForm({...customerForm, address: e.target.value})}
              rows="3"
              style={{
                width: '100%',
                padding: '0.75rem',
                background: '#1d1429',
                border: '1px solid #2d2438',
                borderRadius: '0.5rem',
                color: '#f1f5f9',
                resize: 'vertical'
              }}
            />
          </div>
          <button 
            onClick={handleAddCustomer}
            style={{
              marginTop: '1.5rem',
              padding: '0.75rem 1.5rem',
              background: 'linear-gradient(135deg, #8c2bee 0%, #7c3aed 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '0.5rem',
              fontWeight: '600',
              cursor: 'pointer'
            }}
          >
            Save Customer
          </button>
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '2rem' }}>
        {/* Customer List */}
        <div style={{
          background: 'rgba(29, 20, 41, 0.6)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(140, 43, 238, 0.1)',
          borderRadius: '0.75rem',
          padding: '1.5rem'
        }}>
          <h3 style={{ color: 'white', marginBottom: '1rem' }}>Customers ({customers.length})</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {customers.map(customer => (
              <div
                key={customer.id}
                onClick={() => setSelectedCustomer(customer)}
                style={{
                  padding: '1rem',
                  background: selectedCustomer?.id === customer.id ? 'rgba(140, 43, 238, 0.2)' : '#1d1429',
                  border: selectedCustomer?.id === customer.id ? '1px solid #8c2bee' : '1px solid #2d2438',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  transition: 'all 0.2s'
                }}
              >
                <div style={{ color: 'white', fontWeight: '600', marginBottom: '0.25rem' }}>{customer.name}</div>
                <div style={{ color: '#94a3b8', fontSize: '0.875rem' }}>{customer.email}</div>
                {customer.phone && <div style={{ color: '#94a3b8', fontSize: '0.875rem' }}>{customer.phone}</div>}
              </div>
            ))}
            {customers.length === 0 && (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No customers yet. Add your first customer!
              </div>
            )}
          </div>
        </div>

        {/* Transaction Selection */}
        <div style={{
          background: 'rgba(29, 20, 41, 0.6)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(140, 43, 238, 0.1)',
          borderRadius: '0.75rem',
          padding: '1.5rem'
        }}>
          <h3 style={{ color: 'white', marginBottom: '1rem' }}>
            Select Transactions {selectedEntries.length > 0 && `(${selectedEntries.length} selected)`}
          </h3>
          <div style={{ maxHeight: '500px', overflowY: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead style={{ position: 'sticky', top: 0, background: 'rgba(29, 20, 41, 0.95)' }}>
                <tr>
                  <th style={{ padding: '0.75rem', textAlign: 'left', color: '#94a3b8', fontSize: '0.75rem', textTransform: 'uppercase' }}>Select</th>
                  <th style={{ padding: '0.75rem', textAlign: 'left', color: '#94a3b8', fontSize: '0.75rem', textTransform: 'uppercase' }}>Date</th>
                  <th style={{ padding: '0.75rem', textAlign: 'left', color: '#94a3b8', fontSize: '0.75rem', textTransform: 'uppercase' }}>Description</th>
                  <th style={{ padding: '0.75rem', textAlign: 'right', color: '#94a3b8', fontSize: '0.75rem', textTransform: 'uppercase' }}>Amount</th>
                </tr>
              </thead>
              <tbody>
                {entries.map(entry => (
                  <tr key={entry.id} style={{ borderBottom: '1px solid #2d2438' }}>
                    <td style={{ padding: '0.75rem' }}>
                      <input
                        type="checkbox"
                        checked={selectedEntries.includes(entry.id)}
                        onChange={() => toggleEntrySelection(entry.id)}
                        style={{ cursor: 'pointer' }}
                      />
                    </td>
                    <td style={{ padding: '0.75rem', color: '#cbd5e1' }}>{entry.date}</td>
                    <td style={{ padding: '0.75rem', color: '#cbd5e1' }}>{entry.description}</td>
                    <td style={{ padding: '0.75rem', color: '#cbd5e1', textAlign: 'right', fontWeight: '600' }}>
                      {formatCurrency(entry.amount)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {selectedEntries.length > 0 && (
            <div style={{ marginTop: '1rem', padding: '1rem', background: 'rgba(140, 43, 238, 0.1)', borderRadius: '0.5rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', color: 'white', fontWeight: '700', fontSize: '1.25rem' }}>
                <span>Total:</span>
                <span>{formatCurrency(calculateTotal())}</span>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Invoice Modal */}
      {showInvoice && invoiceData && invoiceData.items && invoiceData.items.length > 0 && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.9)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000,
          padding: '2rem'
        }} onClick={() => setShowInvoice(false)}>
          <div style={{
            background: 'white',
            borderRadius: '0.75rem',
            maxWidth: '900px',
            width: '100%',
            maxHeight: '90vh',
            overflow: 'auto',
            position: 'relative'
          }} onClick={(e) => e.stopPropagation()}>
            <div style={{ padding: '2rem' }}>
              {/* Invoice Header */}
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '2rem', borderBottom: '2px solid #e2e8f0', paddingBottom: '1rem' }}>
                <div>
                  <h2 style={{ color: '#8c2bee', fontSize: '2rem', fontWeight: '700', margin: 0 }}>INVOICE</h2>
                  <p style={{ color: '#64748b', margin: '0.5rem 0 0 0' }}>FinanceGuard Pro</p>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p style={{ margin: '0.25rem 0', color: '#1e293b' }}><strong>Invoice #:</strong> {invoiceData.invoiceNumber}</p>
                  <p style={{ margin: '0.25rem 0', color: '#1e293b' }}><strong>Date:</strong> {invoiceData.date}</p>
                </div>
              </div>

              {/* Customer Details */}
              <div style={{ marginBottom: '2rem' }}>
                <h3 style={{ color: '#1e293b', marginBottom: '0.5rem' }}>Bill To:</h3>
                <p style={{ margin: '0.25rem 0', color: '#1e293b' }}><strong>{invoiceData.customer.name}</strong></p>
                <p style={{ margin: '0.25rem 0', color: '#64748b' }}>{invoiceData.customer.email}</p>
                {invoiceData.customer.phone && <p style={{ margin: '0.25rem 0', color: '#64748b' }}>{invoiceData.customer.phone}</p>}
                {invoiceData.customer.address && <p style={{ margin: '0.25rem 0', color: '#64748b' }}>{invoiceData.customer.address}</p>}
                {invoiceData.customer.gst && <p style={{ margin: '0.25rem 0', color: '#64748b' }}>GST: {invoiceData.customer.gst}</p>}
              </div>

              {/* Invoice Items */}
              <table style={{ width: '100%', marginBottom: '2rem', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ background: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                    <th style={{ padding: '0.75rem', textAlign: 'left', color: '#1e293b' }}>Date</th>
                    <th style={{ padding: '0.75rem', textAlign: 'left', color: '#1e293b' }}>Description</th>
                    <th style={{ padding: '0.75rem', textAlign: 'right', color: '#1e293b' }}>Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {invoiceData.items.map(item => (
                    <tr key={item.id} style={{ borderBottom: '1px solid #e2e8f0' }}>
                      <td style={{ padding: '0.75rem', color: '#64748b' }}>{item.date}</td>
                      <td style={{ padding: '0.75rem', color: '#1e293b' }}>{item.description}</td>
                      <td style={{ padding: '0.75rem', textAlign: 'right', color: '#1e293b' }}>{formatCurrency(item.amount)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>

              {/* Totals */}
              <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <div style={{ width: '300px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '0.5rem 0', borderBottom: '1px solid #e2e8f0' }}>
                    <span style={{ color: '#64748b' }}>Subtotal:</span>
                    <span style={{ color: '#1e293b', fontWeight: '600' }}>{formatCurrency(invoiceData.subtotal)}</span>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '0.5rem 0', borderBottom: '1px solid #e2e8f0' }}>
                    <span style={{ color: '#64748b' }}>GST (18%):</span>
                    <span style={{ color: '#1e293b', fontWeight: '600' }}>{formatCurrency(invoiceData.tax)}</span>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '0.75rem 0', background: '#f8fafc', marginTop: '0.5rem', paddingLeft: '1rem', paddingRight: '1rem', borderRadius: '0.5rem' }}>
                    <span style={{ color: '#1e293b', fontWeight: '700', fontSize: '1.125rem' }}>Total:</span>
                    <span style={{ color: '#8c2bee', fontWeight: '700', fontSize: '1.125rem' }}>{formatCurrency(invoiceData.total)}</span>
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div style={{ display: 'flex', gap: '1rem', marginTop: '2rem', justifyContent: 'flex-end' }}>
                <button 
                  onClick={() => setShowInvoice(false)}
                  style={{
                    padding: '0.75rem 1.5rem',
                    background: '#e2e8f0',
                    color: '#1e293b',
                    border: 'none',
                    borderRadius: '0.5rem',
                    fontWeight: '600',
                    cursor: 'pointer'
                  }}
                >
                  Close
                </button>
                <button 
                  onClick={handlePrintInvoice}
                  style={{
                    padding: '0.75rem 1.5rem',
                    background: 'linear-gradient(135deg, #8c2bee 0%, #7c3aed 100%)',
                    color: 'white',
                    border: 'none',
                    borderRadius: '0.5rem',
                    fontWeight: '600',
                    cursor: 'pointer'
                  }}
                >
                  Print Invoice
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerInvoice;
